    Window_SendEvent5(w, 0, 0x7a, 0x2ee2, 0x4c6b40, 0, 0);
    Window_SendEvent5(w, 0, 0x79, 0x2ee1, 0x4c6bb0, 0, 0);
    Window_SendEvent5(w, 0, 0x79, 0x2ee2, 0x4c6bb0, 0, 0);
