    if (!foreign) foreign = &dummy;
    uint32_t owner = company ? *company : 0;
    *cost = 0;
    *foreign = 0;
    if (from == -1 || to == -1) {
        *cost = 0xffffffff;
        return -1;
    }
    Collection* nodes = hook::Global<Collection*>(0x6cfca8);
    auto node = [&](int32_t id) { return (uint8_t*)Collection_Get(nodes, 0, (uint32_t)id); };
    uint8_t* p1 = node(from);
    uint8_t* p2 = node(to);
    if (!Collection_IsValid(hook::Global<Collection*>(0x6cfcb4), 0, F<uint32_t>(p1, 0x212)) ||
        !Collection_IsValid(hook::Global<Collection*>(0x6cfcb4), 0, F<uint32_t>(p2, 0x212))) {
        *cost = 0xffffffff;
        return -1;
    }
    if (needFlag && !p1[0x44]) {
        *cost = 0xffffffff;
        return -1;
    }
    if (from == to) return from;
    if (Node_IsRouteEnd(p1) && Node_IsRouteEnd(p2)) return Route_FindForVersion(routes, 0, from, to, cost, -1, needFlag, company, foreign, anyTrack);
